package com.nexuszero.mt;
import android.graphics.drawable.Drawable;import androidx.annotation.NonNull;import bin.mt.plugin.api.drawable.MaterialIcons;import bin.mt.plugin.api.editor.*;import bin.mt.plugin.api.ui.PluginUI;import com.nexuszero.mt.core.*;
public final class NexusStringsMenu extends BaseTextEditorToolMenu{@NonNull public String name(){return "NEXUS Strings";}@NonNull public Drawable icon(){return MaterialIcons.get("text_fields");}public boolean checkVisible(@NonNull TextEditor e){return true;}public void onMenuClick(@NonNull PluginUI ui,@NonNull TextEditor e){int a=e.getSelectionStart(),b=e.getSelectionEnd();if(a==b){a=0;b=e.length();}String s=e.subText(a,b);ui.buildDialog().setTitle("NEXUS Strings").setMessage(UniversalAnalyzer.strings(s)).setPositiveButton("{ok}",null).show();}}